UPDATE road_monitor
SET monitor_status = #{monitorStatus}
WHERE road_id IN

    #{roadId}

mapper.select:
SELECT rm.id, rm.monitor_code, rm.road_id, rm.device_id, rm.config_id,
rf.road_name, device.device_code, device.online_status AS deviceOnlineStatus,
rm.pothole_num, rm.crack_length, rm.road_temp, rm.traffic_flow,
rm.pothole_num_threshold, rm.crack_length_threshold, rm.road_temp_threshold, rm.traffic_flow_threshold, rm.collect_frequency_snapshot,
rm.is_warning, rm.warning_id_list_str, rm.monitor_status, rm.staff_id, rm.staff_name, rm.sync_duration, rm.record_time, rm.create_time, rm.update_time,
rm.ext_common1, rm.ext_common2, rm.ext_common3, rm.ext_common4
FROM road_monitor rm LEFT JOIN road_facility rf ON rm.road_id = rf.id LEFT JOIN sys_device device ON rm.device_id = device.id
WHERE rm.deleted = 0
AND rf.road_name LIKE CONCAT('%', #{roadName}, '%')
AND device.device_code = #{deviceCode}
AND device.online_status = #{deviceOnlineStatus}
AND rm.is_warning = #{isWarning}
AND rm.monitor_status = #{monitorStatus}
AND rm.update_time >= #{startUpdateTime}
AND rm.update_time <= #{endUpdateTime}
ORDER BY rm.record_time DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM road_monitor rm
LEFT JOIN road_facility rf ON rm.road_id = rf.id
LEFT JOIN sys_device device ON rm.device_id = device.id

WHERE rm.deleted = 0


    AND rf.road_name = #{roadName}



    AND device.device_code = #{deviceCode}



    AND device.online_status = #{deviceOnlineStatus}



    AND rm.is_warning = #{isWarning}



    AND rm.monitor_status = #{monitorStatus}




    AND rm.update_time >= #{startUpdateTime}




    AND rm.update_time <= #{endUpdateTime}

SELECT DISTINCT DATE_FORMAT(record_time,'%Y-%m-%d %H:00:00') as record_time
FROM road_monitor
WHERE record_time BETWEEN #{startTime} AND #{endTime}

    AND road_id = #{roadId}

ORDER BY record_time ASC

SELECT AVG(pothole_num)
FROM road_monitor
WHERE DATE_FORMAT(record_time,'%Y-%m-%d %H:00:00') = #{recordTime}
AND deleted = 0

    AND road_id = #{roadId}

SELECT AVG(crack_length)
FROM road_monitor
WHERE DATE_FORMAT(record_time,'%Y-%m-%d %H:00:00') = #{recordTime}
AND deleted = 0

    AND road_id = #{roadId}

SELECT AVG(road_temp)
FROM road_monitor
WHERE DATE_FORMAT(record_time,'%Y-%m-%d %H:00:00') = #{recordTime}
AND deleted = 0

    AND road_id = #{roadId}

SELECT AVG(traffic_flow)
FROM road_monitor
WHERE DATE_FORMAT(record_time,'%Y-%m-%d %H:00:00') = #{recordTime}
AND deleted = 0

    AND road_id = #{roadId}
